const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8');
  let pos = 0;
  const len = data.length;

  function nextInt() {
    while (pos < len && data.charCodeAt(pos) <= 32) pos++;
    let num = 0;
    while (pos < len) {
      const c = data.charCodeAt(pos);
      if (c <= 32) break;
      num = num * 10 + (c - 48);
      pos++;
    }
    return num;
  }

  function nextChar() {
    while (pos < len && data.charCodeAt(pos) <= 32) pos++;
    return data[pos++];
  }

  const N = nextInt();
  const M = nextInt();
  const P = nextInt();

  const rowMap = new Int32Array(N + 1);
  for (let i = 1; i <= N; i++) rowMap[i] = i;

  const colMap = new Int32Array(M + 1);
  for (let j = 1; j <= M; j++) colMap[j] = j;

  for (let k = 0; k < P; k++) {
    const op = nextChar();
    const a = nextInt();
    const b = nextInt();

    if (op === 'L') {
      const tmp = rowMap[a];
      rowMap[a] = rowMap[b];
      rowMap[b] = tmp;
    } else {
      const tmp = colMap[a];
      colMap[a] = colMap[b];
      colMap[b] = tmp;
    }
  }

  const out = [];
  let buf = '';

  for (let i = 1; i <= N; i++) {
    const base = (rowMap[i] - 1) * M;
    let line;

    if (M === 1) {
      line = (base + colMap[1]) + '\n';
    } else {
      const row = new Array(M);
      for (let j = 1; j <= M; j++) {
        row[j - 1] = base + colMap[j];
      }
      line = row.join(' ') + '\n';
    }

    buf += line;
    if (buf.length >= 65536) {
      out.push(buf);
      buf = '';
    }
  }

  if (buf.length > 0) out.push(buf);
  process.stdout.write(out.join(''));
}

main();
